  XW += x[8] * 2.8009999999999998e+01;  // CO
  XW += x[9] * 7.8114000000000004e+01;  // C6H6
  XW += x[10] * 2.6037999999999997e+01; // C2H2
  XW += x[11] * 9.2140999999999991e+01; // C6H5CH3
  XW += x[12] * 1.5035000000000000e+01; // CH3
  XW += x[13] * 3.1998000000000001e+01; // O2
  XW += x[14] * 1.5999000000000001e+01; // O
  XW += x[15] * 1.7007000000000001e+01; // OH
  XW += x[16] * 3.3006000000000000e+01; // HO2
  XW += x[17] * 1.8015000000000001e+01; // H2O
  XW += x[18] * 3.4014000000000003e+01; // H2O2
  XW += x[19] * 1.0080000000000000e+00; // H
  XW += x[20] * 3.0026000000000000e+01; // CH2O
  XW += x[21] * 4.4009000000000000e+01; // CO2
  XW += x[22] * 4.2036999999999999e+01; // CH2CO
  XW += x[23] * 3.9057000000000002e+01; // C3H3
  XW += x[24] * 4.1073000000000000e+01; // aC3H5
  XW += x[25] * 8.0085999999999984e+01; // C5H4O
  XW += x[26] * 6.5094999999999999e+01; // C5H5
  XW += x[27] * 9.1132999999999996e+01; // C6H5CH2
  XW += x[28] * 9.3105000000000004e+01; // C6H5O
  XW += x[29] * 1.0612400000000000e+02; // C6H5CHO
