    qr[94] = k_f[94] *
             (kc_fast ? (inv_ge[6] * ge[7] * ge[19] * inv_ge_qss[5])
                      : exp(-(-g_RT[6] + g_RT[7] + g_RT[19] - g_RT_qss[5]))) *
             (sc[6]);
