  // reaction 169: C6H5 + CH3 <=> C6H5CH3
  qf[169] = sc[12] * sc_qss[8];
  qr[169] = sc[11];

  // reaction 170: C6H5CH3 + O2 <=> C6H5CH2 + HO2
  qf[170] = sc[11] * sc[13];
  qr[170] = sc[16] * sc[27];

  // reaction 171: C6H5CH3 + OH <=> C6H5CH2 + H2O
  qf[171] = sc[11] * sc[15];
  qr[171] = sc[17] * sc[27];

  // reaction 172: C6H5CH3 + H <=> C6H5CH2 + H2
  qf[172] = sc[11] * sc[19];
  qr[172] = sc[6] * sc[27];

  // reaction 173: C6H5CH3 + H <=> C6H6 + CH3
  qf[173] = sc[11] * sc[19];
