  // reaction 181: C6H5CHO + OH <=> C6H5CO + H2O
  qf[181] = sc[15] * sc[29];
  qr[181] = sc[17] * sc_qss[9];

  // reaction 182: C6H5CHO + H <=> C6H5CO + H2
  qf[182] = sc[19] * sc[29];
  qr[182] = sc[6] * sc_qss[9];

  // reaction 183: C6H5CHO + H <=> C6H6 + HCO
  qf[183] = sc[19] * sc[29];
  qr[183] = sc[9] * sc_qss[2];

  // reaction 184: C6H5CHO + O <=> C6H5CO + OH
  qf[184] = sc[14] * sc[29];
